export default "<template>\r\n    <b-container fluid>\r\n\r\n        <raw-loader v-show=\"level == 9\" :mytxt=\"require('!raw-loader!./TableProviderThu.vue').default\"\r\n            :btnText=\"`Code TableProviderThu [${level}]`\"></raw-loader>\r\n        \r\n        <div v-if=\"showData\">\r\n            {{ cacheItems }}  \r\n        </div>  \r\n\r\n        <b-table \r\n            ref=\"mytable\" \r\n            :items=\"myProvider\" \r\n            :fields=\"fields\" \r\n            :total-rows=\"totalRows\" \r\n            :per-page=\"perPage\"\r\n            :current-page.sync=\"currentPage\" :filter=\"filter\" :sort-by.sync=\"sortBy\" :sort-desc.sync=\"sortDesc\" \r\n            small\r\n            bordered \r\n            outlined\r\n            stacked=\"md\"\r\n\r\n            >\r\n            <!-- STT -->\r\n            <template #cell(STT)=\"data\">\r\n                {{ data.index + 1 }}\r\n            </template>\r\n            <template v-slot:cell()=\"{ value, item, field: { key } }\">\r\n                <!--row view-->\r\n                <template v-if=\"sel.Id != item.Id\">\r\n                    <template v-if=\"item['Id'] != 0\">\r\n                        <template v-if=\"key == 'Done'\">\r\n                            <input type=\"checkbox\" :checked=\"(value == true) ? true : false\" :disabled=\"true\" />\r\n                        </template>\r\n                        <!--Row view default-->\r\n                        <template v-else>\r\n                            {{ value }}\r\n                        </template>\r\n                        <!--Row view default-->\r\n                    </template>\r\n                </template>\r\n\r\n                <!--row edit-->\r\n                <template v-if=\"(sel.Id == item.Id || item.Id == 0)\">\r\n                    <template v-if=\"key == 'Id'\">\r\n                        {{ value }}\r\n                    </template>\r\n                    <template v-else-if=\"key == '_Tien'\">\r\n                        {{ value }}-hello\r\n                    </template>\r\n                    <template v-else-if=\"key == 'Ngay'\">\r\n                        <b-form-datepicker v-model=\"sel[key]\" :date-format-options=\"{\r\n                            year: 'numeric',\r\n                            month: 'numeric',\r\n                            day: 'numeric',\r\n                        }\" locale=\"vi\" class=\"\">\r\n                        </b-form-datepicker>\r\n                    </template>\r\n                    <template v-else-if=\" key=='TienThu' \">\r\n                        <b-form-input autocomplete=\"off\" v-model=\"sel[key]\" :name=\"key\" v-validate=\"'required'\"\r\n                            placeholder=\"\" :class=\"{ 'ko-hop-le': errors.has(key), 'text-center': true }\">\r\n                        </b-form-input>\r\n                    </template>\r\n\r\n\r\n\r\n                    <template v-else-if=\"key == '_Done'\">\r\n                        <b-form-checkbox class=\"my-checkbox\" v-model=\"sel[key]\" :name=\"key\" :value=true\r\n                            :unchecked-value=false></b-form-checkbox>\r\n                    </template>\r\n                    <template v-else-if=\"key == '_MonId'\">\r\n                        <v-select :clearable=\"false\" v-model=\"sel[key]\" v-validate=\"'required'\" :name=\"key\"\r\n                            :reduce=\"(option) => option.id\" \r\n                            :options=\"monAns\" \r\n                            :has-error=\"errors.has(key)\" :class=\"{ danger: errors.has(key) }\" />\r\n                    </template>\r\n                    <!--Row edit default-->\r\n                    <template v-else>\r\n                        <b-form-input autocomplete=\"off\" v-model=\"sel[key]\" :name=\"key\" v-validate=\"'required'\"\r\n                            placeholder=\"\" :class=\"{ 'ko-hop-le': errors.has(key), 'text-center': false }\">\r\n                        </b-form-input>\r\n                    </template>\r\n                    <!--Row edit default-->\r\n                </template>\r\n            </template>\r\n            <!-- ACTION -->\r\n            <template #cell(actions)=\"row\">\r\n                <template v-if=\"sel.Id !== row.item.Id\">\r\n                    <button class=\"mr-1\" @click=\"onEdit(row.item)\">Edit</button>\r\n                    <button class=\"mr-1\" @click=\"onDel(row.item)\">Del</button>\r\n                </template>\r\n                <template v-else>\r\n                    <button class=\"mr-1\" @click=\"onUpdate()\">\r\n                        {{ sel.Id ? 'Update' : 'Add' }}\r\n                    </button>\r\n                    <button @click=\"onCancel()\">Cancel</button>\r\n                </template>\r\n            </template>\r\n        </b-table>\r\n        <b-row class=\"mt-2\">\r\n            <b-col>\r\n                <div class=\"d-flex flex-column flex-md-row align-items-md-center\">\r\n\r\n                    <!-- Add -->\r\n                    <b-button @click=\"onAdd\" variant=\"primary\" class=\"mb-2 mb-md-0 mr-md-3\">\r\n                        Add\r\n                    </b-button>\r\n\r\n                    <!-- Search -->\r\n                    <b-input-group class=\"mb-2 mb-md-0 mr-md-3\" style=\"max-width: 300px;\">\r\n                        <b-form-input v-model=\"filter\" placeholder=\"Search...\" />\r\n                        <b-input-group-append v-if=\"filter\">\r\n                            <b-button @click=\"onClear\" variant=\"outline-secondary\">✕</b-button>\r\n                        </b-input-group-append>\r\n                    </b-input-group>\r\n\r\n                    <!-- Per page -->\r\n                    <div class=\"d-flex align-items-center mb-2 mb-md-0 mr-md-3\">\r\n                        <span class=\"mr-2\">Per page:</span>\r\n                        <b-form-select v-model=\"perPage\" :options=\"[3, 5, 10]\" style=\"width: 80px;\" />\r\n                    </div>\r\n\r\n                    <!-- Pagination -->\r\n                    <b-pagination class=\"ml-md-auto\" v-model=\"currentPage\" :total-rows=\"totalRows\"\r\n                        :per-page=\"perPage\" />\r\n\r\n                </div>\r\n            </b-col>\r\n        </b-row>\r\n    </b-container>\r\n</template>\r\n\r\n<script>\r\n//import { taBiLuService } from '@/db/taBiLuService';\r\nimport { hoaDonService } from '@/db/hoaDonService';\r\nimport { thuService } from '@/db/thuService';\r\nexport default {\r\n    computed: {\r\n        user() {\r\n            return JSON.parse(localStorage.getItem('user') || '{}')\r\n        },\r\n        level() {\r\n            return this.user.level || 0\r\n        }\r\n    },\r\n    data() {\r\n        return {\r\n            Service: thuService, //taBiLuService,\r\n            showData:false,\r\n\r\n            sel: {},\r\n            add: false,\r\n            edit: false,\r\n\r\n            isPagingDisabled: false,\r\n            isPerPageDisabled: false,\r\n            isFilterDisabled: false,\r\n\r\n            cacheItems: [],\r\n\r\n            rec: {\r\n                Id: 0,\r\n                Ngay: new Date(),\r\n                TienThu:10000,\r\n                GhiChu:'ghi chú',\r\n                // TenKhach: 'thuc 101',\r\n                // Tien: 30000,\r\n                // Done: true,\r\n                // MonId: 1,\r\n            },\r\n\r\n            fields: [\r\n                { key: 'STT', label: 'STT', class: \"text-center\", sortable: true, thClass: \"text-left\", tdClass: \"align-middle\", thStyle: { width: \"5%\" } },\r\n                { key: 'Id', label: 'Id', class: \"text-center\", sortable: true, thClass: \"text-left\", tdClass: \"align-middle\", thStyle: { width: \"5%\" } },\r\n                { key: 'Ngay', label: 'Ngày', class: \"text-center\", sortable: true, thClass: \"text-center\", tdClass: \"align-middle\", thStyle: { width: \"10%\" } , formatter:'fmtDate' },\r\n                { key: 'TienThu', label: 'Tiền thu', class: \"text-center\", sortable: true, thClass: \"text-center\", tdClass: \"align-middle\", thStyle: { width: \"10%\" } , formatter: v => Number(v).toLocaleString('vi-VN') },\r\n                { key: 'GhiChu', label: 'Ghi chú', class: \"text-left\", sortable: true, thClass: \"text-center\", tdClass: \"align-middle\", thStyle: { width: \"50%\" }  },\r\n                { key: 'actions', label: 'Actions', class: \"text-center\", thClass: \"text-center\", tdClass: \"align-middle\", thStyle: { width: \"20%\" } }\r\n            ],\r\n            totalRows: 0,\r\n            currentPage: 1,\r\n            perPage: 3,\r\n\r\n            sortBy: '',\r\n            sortDesc: false,\r\n            filter: null,\r\n            \r\n            monAns:[\r\n                { id: 1, label: 'Đường' },\r\n                { id: 2, label: 'Sữa' },\r\n                { id: 3, label: 'Bột' },\r\n            ],\r\n\r\n        }\r\n    },\r\n\r\n    methods: {\r\n\r\n        // ================= PROVIDER =================\r\n        async myProvider(ctx) {\r\n            let res = await this.Service.getPagingCursor({\r\n                page: ctx.currentPage,\r\n                pageSize: ctx.perPage,\r\n                keyword: ctx.filter\r\n            })\r\n            this.totalRows = res.total\r\n            let data = res.items\r\n            data = data.sort((a, b) => b.Id - a.Id)\r\n            if (this.add) {\r\n                data = [this.rec, ...data]\r\n                this.sel = { ...this.rec }\r\n            }\r\n            this.cacheItems = data\r\n            return data\r\n        },\r\n\r\n        // ================= ADD =================\r\n\r\n        async onAdd() {\r\n            if (this.add || this.edit) return\r\n\r\n            this.add = true\r\n            await this.$refs.mytable.refresh()\r\n            this.currentPage = 1;\r\n        },\r\n\r\n        // ================= EDIT =================\r\n        onEdit(item) {\r\n            if (this.add || this.edit) return\r\n            this.sel = { ...item }\r\n            this.edit = true\r\n        },\r\n\r\n        // ================= DELETE =================\r\n        async onDel(item) {\r\n            if (this.add || this.edit) return\r\n            await this.Service.delete(item.Id)\r\n            await this.$refs.mytable.refresh()\r\n        },\r\n\r\n        // ================= SAVE =================\r\n\r\n        async onUpdate() {\r\n            let result = await this.$validator.validateAll();\r\n            if (!result) {\r\n                this.toast(`Dữ liệu không hợp lệ`);\r\n                return;\r\n            }\r\n\r\n            const r = { ...this.sel }\r\n            if (r.Id == 0) {\r\n                const { Id, ...newr } = r\r\n                await this.Service.add(newr)\r\n            } else {\r\n                await this.Service.update(r)\r\n            }\r\n            await this.$refs.mytable.refresh()\r\n            this.currentPage = 1;\r\n            this.add = false;\r\n            this.sel = {};\r\n            this.edit = false;\r\n        },\r\n\r\n        // ================= CANCEL =================\r\n        async onCancel() {\r\n            await this.$refs.mytable.refresh();\r\n            this.add = false;\r\n            this.sel = {};\r\n            this.edit = false;\r\n        },\r\n\r\n        // ================= RESET =================\r\n        resetState() {\r\n            this.sel = {}\r\n            this.add = false\r\n            this.edit = false\r\n        },\r\n\r\n        NgayFormat(date) {\r\n            if (!date) return ''\r\n            const d = new Date(date)\r\n            const day = String(d.getDate()).padStart(2, '0')\r\n            const month = String(d.getMonth() + 1).padStart(2, '0')\r\n            const year = d.getFullYear()\r\n            return `${day}/${month}/${year}`\r\n        },\r\n        TienFormat(tien) {\r\n            return `${Number(tien).toLocaleString()} đ`\r\n        },\r\n        async onClear() {\r\n            this.filter = null\r\n            this.currentPage = 1\r\n            await this.$refs.mytable.refresh()\r\n        },\r\n        \r\n        toast(msg, variant = null) {\r\n            this.$bvToast.toast(msg, {\r\n                title: `Information`,\r\n                variant: variant,\r\n                solid: true,\r\n            });\r\n        },\r\n        fmtDate(v) {\r\n            if (!v) return ''\r\n            const d = new Date(v)\r\n            return `${d.getDate().toString().padStart(2,'0')}/${\r\n            (d.getMonth()+1).toString().padStart(2,'0')\r\n            }/${d.getFullYear()}`\r\n        }        \r\n\r\n    }\r\n}\r\n</script>";